#include <bits/stdc++.h>
using namespace std;
int main(){map<pair<int,int>,int> inv;vector<unsigned> reps{0};for(int n=1;n<=7;n++){int m=n*(n-1)/2; vector<unsigned> next;set<int> vals,strongvals;vector<char> seen;if(n<8)seen.resize(1u<<m);unsigned candidates=0;auto visit=[&](unsigned code){unsigned out[8]={};int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++){if((code>>k)&1)out[i]|=1<<j;else out[j]|=1<<i;} int dp[256][8]={};for(int s=1;s<(1<<n);s++){for(int v=0;v<n;v++)if(s>>v&1){if(s==(1<<v))dp[s][v]=1;else for(int u=0;u<n;u++)if((s>>u&1)&&(out[u]>>v&1))dp[s][v]+=dp[s^(1<<v)][u];}}int h=accumulate(dp[(1<<n)-1],dp[(1<<n)-1]+n,0);vals.insert(h);bool strong=1;for(int v=0;v<n;v++){unsigned r=1<<v;for(int t=0;t<n;t++)for(int u=0;u<n;u++)if(r>>u&1)r|=out[u];if(r!=(1u<<n)-1)strong=0;}if(strong)strongvals.insert(h);candidates++;if(n==8||seen[code])return;if(strong && (h==3||h==5||h==9||h==15||h==25))inv[{h,n}]++;next.push_back(code);int p[8];iota(p,p+n,0);do{unsigned c=0;int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++)if(out[p[i]]>>p[j]&1)c|=1u<<k;seen[c]=1;}while(next_permutation(p,p+n));};if(n==1)visit(0);else for(unsigned old:reps)for(int a=0;a<(1<<(n-1));a++){unsigned c=0;int ko=0,kn=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,kn++){bool bit;if(j<n-1)bit=old>>ko++&1;else bit=a>>i&1;if(bit)c|=1<<kn;}visit(c);}cout<<n<<" classes="<<next.size()<<" candidates="<<candidates<<" all="<<vals.size()<<" strong="<<strongvals.size()<<" max="<<*vals.rbegin()<<" gaps=";for(int h=1;h<=*vals.rbegin();h+=2)if(!vals.count(h))cout<<h<<",";cout<<"\n";reps=next;} map<pair<int,int>,int> expected{{{3,3},1},{{5,4},1},{{9,5},2},{{15,5},2},{{15,6},2},{{25,6},2},{{25,7},1}};assert(inv==expected);for(auto [key,c]:inv)cout<<"inventory H="<<key.first<<" n="<<key.second<<" classes="<<c<<"\n";cout<<"PASS complete strong inventories through order7\n";}
